<template><nav class="ln-pagination" aria-label="分页"><span class="ln-pagination__total">共 {{total}} 条</span><select :value="pageSize" aria-label="每页数量" @change="changeSize"><option v-for="size in pageSizes" :key="size" :value="size">{{size}} / 页</option></select><div class="ln-pagination__controls"><button type="button" :disabled="page<=1" aria-label="上一页" @click="setPage(page-1)"><LnIcon name="chevron-left"/></button><button v-for="item in pages" :key="item" type="button" :class="{active:item===page}" @click="setPage(item)">{{item}}</button><button type="button" :disabled="page>=pageCount" aria-label="下一页" @click="setPage(page+1)"><LnIcon name="chevron-right"/></button></div><span class="ln-pagination__jump">前往 <input :value="page" type="number" min="1" :max="pageCount" @change="jump"/> 页</span></nav></template>
<script setup lang="ts">
import{computed}from'vue';import LnIcon from './LnIcon.vue';const props=withDefaults(defineProps<{page:number;pageSize:number;total:number;pageSizes?:number[]}>(),{pageSizes:()=>[10,20,50,100]});const emit=defineEmits<{(e:'update:page',value:number):void;(e:'update:pageSize',value:number):void;(e:'change'):void}>();const pageCount=computed(()=>Math.max(1,Math.ceil(props.total/props.pageSize)));const pages=computed(()=>{const start=Math.max(1,Math.min(props.page-2,pageCount.value-4));const end=Math.min(pageCount.value,start+4);return Array.from({length:end-start+1},(_,i)=>start+i)});function setPage(value:number){const next=Math.max(1,Math.min(value,pageCount.value));if(next===props.page)return;emit('update:page',next);emit('change')}function changeSize(e:Event){emit('update:pageSize',Number((e.target as HTMLSelectElement).value));emit('update:page',1);emit('change')}function jump(e:Event){setPage(Number((e.target as HTMLInputElement).value))}
</script>
<style scoped lang="scss">.ln-pagination{min-height:48px;padding:8px 12px;display:flex;align-items:center;justify-content:flex-end;gap:10px;color:var(--ln-text-tertiary);font:12px var(--ln-font)}.ln-pagination select,.ln-pagination input{height:28px;border:1px solid var(--ln-border);border-radius:5px;background:var(--ln-surface);color:var(--ln-text-secondary);outline:0;font:12px var(--ln-font)}.ln-pagination select{padding:0 7px}.ln-pagination input{width:44px;padding:0 5px;text-align:center}.ln-pagination__controls{display:flex;gap:2px;button{min-width:28px;height:28px;padding:0 6px;display:grid;place-items:center;border:0;border-radius:5px;background:transparent;color:var(--ln-icon);cursor:pointer;&:hover:not(:disabled){background:var(--ln-surface-hover);color:var(--ln-text)}&.active{background:var(--ln-accent-soft);color:var(--ln-accent);font-weight:600}&:disabled{opacity:.35;cursor:default}svg{width:14px;height:14px}}}.ln-pagination__jump{display:flex;align-items:center;gap:5px}@media(max-width:720px){.ln-pagination__total,.ln-pagination__jump{display:none}}</style>
